import json, time, sys, urllib.request, urllib.error
from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP
from collections import Counter

BASE = "http://localhost:8080"
log = []
stats = Counter()
token = None

def raw(method, path, auth=True):
    req = urllib.request.Request(BASE + path, method=method)
    if auth and token:
        req.add_header("Authorization", "Bearer " + token)
    try:
        with urllib.request.urlopen(req, timeout=30) as r:
            return r.status, dict(r.headers), r.read()
    except urllib.error.HTTPError as e:
        return e.code, dict(e.headers), e.read()
    except Exception as e:
        return None, {}, repr(e).encode()

def new_token():
    global token
    while True:
        s, h, b = raw("POST", "/token", auth=False)
        if s == 200:
            token = json.loads(b)["token"]; stats["tokens"] += 1; return
        handle_backoff(s, h, b, "/token")

def handle_backoff(s, h, b, path):
    stats[f"status_{s}"] += 1
    if s == 429:
        wait = float(h.get("Retry-After") or json.loads(b).get("retry_after", 1))
        time.sleep(wait)
    else:
        log.append(f"{path}: {s} {b[:200]!r}")
        time.sleep(0.5)

def get(path, allow404=False):
    if token is None: new_token()
    for attempt in range(200):
        s, h, b = raw("GET", path)
        if s == 200:
            try:
                return json.loads(b)
            except Exception:
                log.append(f"{path}: bad json {b[:200]!r}"); stats["badjson"] += 1; continue
        if s == 404 and allow404:
            return None
        if s in (401, 403):
            stats[f"status_{s}"] += 1; new_token(); continue
        handle_backoff(s, h, b, path)
    raise RuntimeError("gave up on " + path)

# --- orders ---
orders = {}           # id -> order
listings = Counter()
conflicts = []
path = "/orders?page=1"
pages_seen = []
total_pages_seen = set()
while path:
    d = get(path)
    pages_seen.append(d.get("page")); total_pages_seen.add(d.get("total_pages"))
    for o in d["items"]:
        listings[o["id"]] += 1
        if o["id"] in orders and orders[o["id"]] != o:
            conflicts.append((orders[o["id"]], o))
        orders.setdefault(o["id"], o)
    path = d.get("next")

dups = sum(c - 1 for c in listings.values())
print("pages", pages_seen, "total_pages", total_pages_seen)
print("listings", sum(listings.values()), "distinct", len(orders), "dups", dups, "conflicts", len(conflicts))
for a, b in conflicts: print("CONFLICT", a, b)

# --- filter ---
lo = datetime(2025, 3, 1, tzinfo=timezone.utc)
hi = datetime(2025, 6, 1, tzinfo=timezone.utc)
statuses = Counter(o["status"] for o in orders.values())
print("statuses", statuses)
def parse(ts):
    t = datetime.fromisoformat(ts.replace("Z", "+00:00"))
    if t.tzinfo is None:
        log.append("naive ts " + ts); t = t.replace(tzinfo=timezone.utc)
    return t.astimezone(timezone.utc)
qual = [o for o in orders.values() if o["status"] == "shipped" and lo <= parse(o["placed_at"]) < hi]

# --- customers (cached) ---
cust = {}
for cid in sorted({o["customer_id"] for o in qual}):
    cust[cid] = get("/customers/" + cid, allow404=True)
missing = [c for c, v in cust.items() if v is None]
print("customers fetched", len(cust), "missing", missing)
print("regions", Counter(v["region"] for v in cust.values() if v), "discounts", Counter(v["discount_pct"] for v in cust.values() if v))

by_region = {"north": 0, "south": 0, "east": 0, "west": 0}
weird = []
for o in qual:
    c = cust[o["customer_id"]]
    if c is None: weird.append(("missing cust", o)); continue
    if not isinstance(o["amount_cents"], int) or not isinstance(c["discount_pct"], int): weird.append(("types", o, c))
    amt = (Decimal(o["amount_cents"]) * (100 - Decimal(c["discount_pct"])) / 100).quantize(Decimal(1), ROUND_HALF_UP)
    by_region[c["region"]] += int(amt)
res = {"total_cents": sum(by_region.values()), "order_count": len(qual) - len([w for w in weird if w[0]=="missing cust"]),
       "duplicates_skipped": dups, "by_region": by_region}
print(json.dumps(res, indent=2))
print("weird", weird)
print("stats", stats)
print("log", log[:30], len(log))
json.dump({"res": res, "orders": orders, "cust": cust, "listings": listings}, open("/tmp/recon/dump.json", "w"))
EOF
cd /tmp && python3 -I /tmp/recon/run.py

